import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ---- Custom CUDA kernel for element-wise addition (FP32) ----
elementwise_add_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

elementwise_add_cpp_source = (
    "torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b);"
)

elementwise_add = load_inline(
    name="elementwise_add",
    cpp_sources=elementwise_add_cpp_source,
    cuda_sources=elementwise_add_source,
    functions=["elementwise_add_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[],
)

# ---- Custom CUDA operator for argmax (FP32) ----
argmax_cpp_source = "torch::Tensor argmax_cuda(torch::Tensor x, int dim);"
argmax_cuda_source = """
torch::Tensor argmax_cuda(torch::Tensor x, int dim) {
    auto cuda_x = x.cuda();
    return torch::argmax(cuda_x, dim=dim).cuda();
}
"""

argmax_cuda = load_inline(
    name="argmax_cuda",
    cpp_sources=argmax_cpp_source,
    cuda_sources=argmax_cuda_source,
    functions=["argmax_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[],
)

class ModelNew(nn.Module):
    def __init__(self, dim: int = None) -> None:
        super().__init__()
        self.dim = dim if dim is not None else 0
        # Keep the custom elementwise_add operator (not used in forward of argmax)
        self.elementwise_add = elementwise_add
        # Expose the custom argmax_cuda operator
        self.argmax_cuda = argmax_cuda

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.argmax_cuda(x, self.dim)
